import { esc,fmt,dateLabel,options,dayKey } from '../utils.js';
import { dayTotals,mealTotals } from './generator.js';
import { calculatePlan } from '../diet/calculations.js';
import { shoppingList } from './shopping.js';
import { button,empty,heading,macroLine } from '../ui/helpers.js';

export function menuView(state,profile,ui) {
  const menu=state.menu,canGenerate=Boolean(profile&&calculatePlan(profile).plan);
  return heading('','Comidas','')+
    `<div class="section-tabs no-print" role="group" aria-label="Secciones de nutrición">${[['plan','Menú semanal'],['shopping','Lista de compra'],['foods','Alimentos']].map(([id,label])=>button('nutrition-tab',label,`data-tab="${id}" aria-pressed="${ui.menuTab===id}"`)).join('')}</div><div id="menu-plan" data-nutrition-panel="plan">`+
    `<div class="toolbar no-print"><label>Semana del<input id="menu-start" type="date" value="${esc(ui.menuStart)}"></label>${canGenerate?button('generate',menu?'Crear otro menú':'Crear menú semanal','','primary'):button('edit-profile','Configurar alimentación','','primary')}${menu?`<details class="quiet-details menu-options"><summary>Más opciones</summary><div class="toolbar">${button('print-menu','Imprimir / guardar PDF')}${button('export-menu','Exportar archivo del menú')}</div></details>`:''}</div>`+
    `<details class="quiet-details"><summary>Raciones y seguridad alimentaria</summary><p class="help">Para una persona: cereales en seco y legumbres cocidas y escurridas. Se usan la dieta y las exclusiones guardadas. Las cantidades son aproximadas: comprueba etiquetas, trazas y cocción segura. Los cambios del perfil se aplican al generar un nuevo menú.</p></details>`+
    (!canGenerate?`<p class="help">Completa tus datos y revisa los avisos para poder crear un menú.</p>`:'')+
    (!menu?empty('Un plan que encaje contigo','Genera tu semana a partir de tus calorías y preferencias.'): `<p class="menu-context">Semana de ${esc(dateLabel(menu.start))} · Objetivo del menú: <strong>${fmt(menu.target.kcal)} kcal/día</strong> · ${menu.profile.meals} comidas</p><div class="day-tabs no-print" role="group" aria-label="Día del menú">${menu.days.map((d,i)=>button('menu-day',esc(dateLabel(d.date)),`data-index="${i}" aria-pressed="${i===ui.menuDay}"`)).join('')}</div><div class="week-menu">${menu.days.map((day,d)=>{
      const totals=dayTotals(day,state.foods),deviation=(totals.kcal/menu.target.kcal-1)*100;
      const macroOff=['protein','carbs','fat'].some(k=>menu.target[k]>0&&Math.abs(totals[k]/menu.target[k]-1)>.2);
      return `<section class="menu-day ${d!==ui.menuDay?'inactive-day':''}"><div class="day-title"><h2>${esc(dateLabel(day.date))}</h2><strong>${fmt(totals.kcal)} kcal</strong></div>${Math.abs(deviation)>10||macroOff?'<p class="notice">Las raciones de este día se alejan de tu objetivo. Revísalas antes de seguir el menú.</p>':''}<details class="quiet-details" data-view-key="nutrients-${day.date}"><summary>Ver nutrientes del día</summary><p class="macro-inline">${macroLine(totals)}</p></details>${day.meals.map((meal,m)=>{
        const n=mealTotals(meal,state.foods),key=day.date+':'+m,consumed=state.consumed[key];
        return `<article class="meal-card"><div class="meal-top"><span class="eyebrow">${esc(meal.label)}</span><span>${fmt(n.kcal)} kcal</span></div><h3>${esc(meal.name)}</h3><details data-view-key="meal-${day.date}-${m}"><summary>Ingredientes y preparación</summary><p class="macro-inline small">${macroLine(n)}</p><ul>${meal.ingredients.map(i=>`<li>${fmt(i.grams)} g · ${esc(state.foods.find(f=>f.id===i.foodId).name)}</li>`).join('')}</ul><p>${esc(meal.steps)}</p></details><div class="meal-actions no-print">${button('lock-meal',meal.locked?'Fijada ✓':'Fijar plato',`data-day="${d}" data-meal="${m}" aria-pressed="${meal.locked}"`)}${button('replace-meal','Cambiar ↻',`data-day="${d}" data-meal="${m}" ${meal.locked?'disabled':''}`)}<label class="check"><input type="checkbox" data-consume="${key}" ${consumed?'checked':''} ${day.date>dayKey()?'disabled':''}> Ya la comí</label></div>${meal.locked?'<p class="help">Plato fijado: se conserva al crear otro menú. Desfíjalo para cambiarlo.</p>':''}</article>`;
      }).join('')}</section>`;
    }).join('')}</div>`)+
    `</div><section class="catalog no-print" data-nutrition-panel="foods"><div class="section-top"><h2>Mis alimentos</h2><span>${state.foods.length} productos</span></div><p class="help">Valores orientativos por 100 g de parte comestible. Comprueba tus etiquetas. Editar un alimento recalcula el menú visible; regénéralo para ajustar raciones. No se garantizan trazas.</p><div class="toolbar">${button('add-food','Añadir alimento')}${button('export-foods','Exportar catálogo JSON')}<label class="file-label">Importar catálogo<input type="file" id="import-foods" accept="application/json,.json"></label></div><label>Buscar alimento<input type="search" id="food-search" value="${esc(ui.foodSearch)}" placeholder="Ej. avena"></label><div id="food-list">${foodRows(state.foods,ui.foodSearch)}</div></section>`;
}
export function foodRows(foods,query='') {return foods.filter(f=>f.name.toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es'))).map(f=>`<div class="catalog-row"><div><strong>${esc(f.name)}</strong><small>${fmt(f.kcal)} kcal · Proteínas ${fmt(f.protein,1)} g · Hidratos ${fmt(f.carbs,1)} g · Grasas ${fmt(f.fat,1)} g / 100 g</small></div>${button('edit-food','Editar',`data-id="${esc(f.id)}"`)}</div>`).join('')||'<p>Sin resultados.</p>';}
export function shoppingView(state) {
  if(!state.menu) return empty('Primero, prepara tu menú','La lista de la compra se crea automáticamente.',button('go-menu','Ir al menú'));
  const list=shoppingList(state.menu,state.foods),sections=[...new Set(list.map(x=>x.section))];
  const bought=list.filter(x=>state.shoppingChecked[x.foodId]).length;
  return `<div class="day-title"><h2>Tu lista de la compra</h2><span>${bought} de ${list.length} comprados</span></div><p class="help">Peso comestible: compra algo más si hay piel, huesos o merma. No incluye agua ni condimentos opcionales.</p><div class="toolbar no-print">${button('print-shopping','Imprimir / guardar PDF')}<details class="quiet-details"><summary>Exportar lista</summary>${button('export-shopping','Descargar hoja de cálculo')}</details></div><div class="shopping-grid">${sections.map(section=>`<section class="shopping-section"><h3>${esc(section)}</h3>${list.filter(i=>i.section===section).map(i=>`<label class="shopping-item ${state.shoppingChecked[i.foodId]?'bought':''}"><input type="checkbox" data-shop="${esc(i.foodId)}" ${state.shoppingChecked[i.foodId]?'checked':''}><span>${esc(i.name)}</span><strong>${i.grams>=1000?fmt(i.grams/1000,2)+' kg':fmt(i.grams,1)+' g'}</strong></label>`).join('')}</section>`).join('')}</div>`;
}
export function foodForm(food) {
  const f=food||{name:'',section:'Despensa',kcal:'',protein:'',carbs:'',fat:'',allergens:[],vegan:true,vegetarian:true};
  return `<form data-form="food" data-id="${esc(food?.id||'')}"><h2>${food?'Editar':'Añadir'} alimento</h2><label>Nombre<input name="name" required maxlength="100" value="${esc(f.name)}"></label><label>Sección de compra<input name="section" required maxlength="80" value="${esc(f.section)}"></label><div class="fields">${[['kcal','Energía (kcal)',1000],['protein','Proteína (g)',100],['carbs','Hidratos (g)',100],['fat','Grasas (g)',100]].map(([key,label,max])=>`<label>${label} / 100 g<input type="number" name="${key}" min="0" max="${max}" step="0.1" required value="${esc(f[key])}"></label>`).join('')}</div><label>Alérgenos / etiquetas (separados por comas)<input name="allergens" maxlength="500" placeholder="gluten, leche, huevo, soja, frutos-secos…" value="${esc(f.allergens.join(', '))}"></label><label class="check"><input type="checkbox" name="vegan" ${f.vegan?'checked':''}> Apto vegano</label><label class="check"><input type="checkbox" name="vegetarian" ${f.vegetarian?'checked':''}> Apto vegetariano</label><p class="help">Elige las etiquetas con cuidado: son parte del filtro de exclusiones.</p><button class="primary">Guardar alimento</button></form>`;
}
